const newId=()=>crypto.randomUUID?.()??'10000000-1000-4000-8000-100000000000'.replace(/[018]/g,c=>(+c^(crypto.getRandomValues(new Uint8Array(1))[0]&15)>>(+c/4)).toString(16));
const priceFormatter=new Intl.NumberFormat('en-US',{maximumFractionDigits:2});const $=s=>document.querySelector(s),rp=n=>n==null?'—':priceFormatter.format(n);
const state={view:'upload',user:null,status:{},items:[],aliases:[],sources:[],selected:0,compiled:null,report:null,filter:'all',page:0,busy:false};
let toastTimer,draftTimer,draftMax,summaryTimer;
function toast(m,error=false){const dialog=document.querySelector('dialog[open]');if(error&&dialog){let out=dialog.querySelector('[data-dialog-error]');if(!out){out=document.createElement('div');out.dataset.dialogError='';out.className='inline-error';out.setAttribute('role','alert');out.tabIndex=-1;dialog.querySelector('.dialog-head').after(out);}out.textContent=m;out.focus();out.scrollIntoView({block:'nearest'});return;}$('#toast').hidden=false;$('#toast').textContent=m;$('#toast').className=error?'error':'';clearTimeout(toastTimer);if(!error)toastTimer=setTimeout(()=>$('#toast').hidden=true,10000);}
async function api(path,method='GET',data){const r=await fetch('/api'+path,{method,headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined,...(['/extract','/review-table','/report-insights'].includes(path)?{signal:AbortSignal.timeout(120000)}:{})});const b=await r.json();if(!r.ok){if(r.status===401&&!['/login','/session'].includes(path)){await persist();state.user=null;login();}throw Error(b.error??'Request gagal.');}return b;}
async function task(button,fn){if(button)button.disabled=true;try{await fn();}catch(e){toast(e.message,true);}finally{if(button?.isConnected)button.disabled=false;}}
function login(){if(state.user?.must_change)return passwordForm();$('#workspace').hidden=true;window.location.replace('/');}
function requireUser(){if(!state.user){login();throw Error('Masuk akun untuk melanjutkan.');}if(state.user.must_change){passwordForm();throw Error('Ganti password sementara terlebih dahulu.');}}
function isAdmin(){return state.user?.role==='admin';}
function canEdit(){return ['admin','editor'].includes(state.user?.role);}
function identity(){document.querySelectorAll('[data-admin-nav]').forEach(b=>b.hidden=!isAdmin());$('#workspace').hidden=!state.user||Boolean(state.user.must_change);const label=state.user?state.user.username+' · '+state.user.role:'';$('#identity').textContent=label;$('#user-label').textContent=label;$('#top-account').textContent='Akun';$('#account').textContent='Akun & pengaturan';}
async function loadMaster(force=false){if(state.user&&!state.user.must_change){if(!force&&state.masterUser===state.user.id&&Date.now()-(state.masterAt??0)<60000)return;const [a,b]=await Promise.all([api('/items'),api('/mappings')]);state.items=a.items;state.aliases=b.mappings;state.categoryRules=b.category_rules??[];state.masterAt=Date.now();state.masterUser=state.user.id;}}
function current(){return state.sources[state.selected];}
function show(view){if(state.busy){toast('Tunggu proses selesai atau batalkan OCR sebelum berpindah halaman.',true);return;}state.view=view;const result=['archive','compile','analysis','reports'].includes(view);document.querySelectorAll('aside [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===(result?'archive':view)));$('#result-nav').hidden=!result;$('#result-nav').querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#title').textContent=({upload:'Masukkan harga',archive:'Hasil · Harga Seragam',compile:'Hasil · Detail Harga',analysis:'Hasil · Analisis',reports:'Hasil · Laporan',settings:'Pengaturan Admin'})[view];task(null,async()=>{requireUser();if(view==='settings'&&!isAdmin())throw Error('Pengaturan hanya untuk Admin.');await measureStage('view:'+view,()=>({upload:uploadPage,archive:archivePage,compile:compilePage,analysis:analysisPage,reports:reportPage,settings:settingsPage})[view]());});}
function sourceState(name,file=null){return {id:newId(),file,filename:name,url:file?URL.createObjectURL(file):'',mime:file?.type??'',supplier:'',valid_from:'',valid_to:'',rows:[],warnings:[],status:'Pilih Proses untuk membaca gambar',revision:1,batch_id:null,rawTable:null,dirty:true,locale:'en-US'};}
async function persist(){clearTimeout(draftTimer);clearTimeout(draftMax);draftMax=null;if(!state.user||!canEdit())return;try{const saved=snapshot(state.sources);await draftStore(state.user.id,saved.length?{sources:saved,at:new Date().toISOString()}:null);const el=$('#draft-status');if(el)el.textContent=current()?.sample?'Latihan lokal · tidak disimpan':saved.length?'Draft di perangkat ini · '+new Date().toLocaleTimeString('id-ID'):'Semua perubahan tersimpan di web';}catch(e){toast(e.message,true);}}
function changed(s){s.dirty=true;s.changeVersion=(s.changeVersion??0)+1;clearTimeout(draftTimer);draftTimer=setTimeout(persist,2000);draftMax??=setTimeout(persist,60000);clearTimeout(summaryTimer);summaryTimer=setTimeout(()=>updateSummary(s),180);}
function mapApproved(s){applyRules(s,state.aliases,state.items);for(const [index,r] of s.rows.entries()){r.source_row??=index+1;if(r.category_id)continue;const a=state.categoryRules?.find(a=>a.supplier===norm(s.supplier)&&a.alias===ruleKey(r)&&a.signature===signature(r)&&(!r.sku||norm(a.raw_name)===norm(r.raw_product||r.product)));if(a&&category(a.category_id)){r.category_id=a.category_id;r.item_id=null;r.in_comparison=true;r.category_origin='approved-rule';}}}
function updateSummary(s){if(s!==current())return;const n=s.rows.filter(r=>issues(r,state.items).length).length;const el=$('#summary');if(el)el.textContent=s.rows.length+' baris · '+n+' perlu diperiksa · '+s.rows.filter(r=>r.category_id).length+' masuk harga seragam';}
function sourcePreview(s){if(s.mime?.startsWith('image/')&&s.url)return `${zoomToolbar()}<div class="source-viewport" tabindex="0" role="region" aria-label="Preview sumber, dapat digeser saat zoom"><div class="source-stage"><img id="source-image" data-zoom-media draggable="false" class="source-preview" src="${esc(s.url)}" alt="Pricelist ${esc(s.filename)}"><canvas id="source-overlay" aria-hidden="true"></canvas></div></div>`;if(s.mime==='application/pdf'&&s.file)return `<label>Halaman PDF<input id="pdf-page" type="number" min="1" value="1"></label><button id="render-pdf">Tampilkan halaman</button>${zoomToolbar()}<div class="source-viewport" tabindex="0" role="region" aria-label="Preview PDF, dapat digeser saat zoom"><div class="source-stage pdf-stage"><canvas id="pdf-canvas" data-zoom-media class="source-preview"></canvas></div></div>`;return `<p>${s.batch_id?'Data tersimpan.':'Preview sumber belum tersedia.'} Pilih kembali file lokal jika perlu memeriksa gambarnya.</p><button id="reattach">Pilih ulang sumber</button>`;}
function highlight(r){const img=$('#source-image'),c=$('#source-overlay');if(!img||!c||!r.source_box)return;const boxKey=JSON.stringify(r.source_box);if(c.dataset.box===boxKey)return;c.dataset.box=boxKey;if(c.width!==img.naturalWidth)c.width=img.naturalWidth;if(c.height!==img.naturalHeight)c.height=img.naturalHeight;const ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);const [a,b,x,y]=r.source_box;ctx.strokeStyle='#f5b75d';ctx.lineWidth=Math.max(2,c.width/450);ctx.strokeRect(a,b,x-a,y-b);}
function warningsHTML(s){return s.warnings.length?`<details class="notice" open><summary>Catatan pembacaan (${s.warnings.length})</summary><ul>${s.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></details>`:'';}
function refreshUploadResult(s){if(state.view!=='upload'||current()!==s||!$('#rows'))return;$('#source-warnings').innerHTML=warningsHTML(s);$('#progress').textContent=s.status;$('#ocr-progress').hidden=true;$('#raw-text-slot').innerHTML=s.rawText?`<details><summary>Teks mentah OCR</summary><pre>${esc(s.rawText)}</pre><button id="paste-table">Susun dari teks yang dikoreksi</button></details>`:'';if($('#paste-table'))$('#paste-table').onclick=()=>pasteTable(s);if($('#process'))$('#process').textContent=s.rows.length?'Baca ulang':'Baca otomatis';if($('#cancel-ocr'))$('#cancel-ocr').hidden=true;renderRows(s);}
const lockedControls=new Map();function lockUpload(lock){if(!lock){for(const [el,disabled] of lockedControls)if(el.isConnected)el.disabled=disabled;lockedControls.clear();return;}for(const el of document.querySelectorAll('#content input,#content select,#content button,#content textarea')){if(el.id==='cancel-ocr')continue;lockedControls.set(el,el.disabled);el.disabled=true;}}
async function processAutomatic(s){try{await processLocal(s);}catch(e){if(!/Poster promosi/.test(e.message))throw e;detail('Pilih cara membaca poster',`<p>Layout ini belum dapat dibaca OCR lokal dengan andal. Bantuan AI mengirim gambar setelah persetujuan Anda dan tetap menghasilkan draft.</p><div class="actions"><button id="poster-ai" class="primary">Bantu baca dengan AI</button><button id="poster-manual">Isi tabel manual</button></div>`);$('#poster-ai').onclick=e=>task(e.target,async()=>{$('#detail').close();await processAI(s);});$('#poster-manual').onclick=()=>{$('#detail').close();if(!s.rows.length)s.rows.push(rawRow({},s.filename));changed(s);refreshUploadResult(s);};}}
function welcomeHTML(){let hidden=state.welcomeHidden;try{hidden??=localStorage.getItem('mis-welcome:'+state.user.id)==='seen';}catch{}return hidden?'':`<section class="welcome notice"><strong>Tiga langkah untuk mulai</strong><div class="welcome-steps"><p>1. Masukkan file dari PT.</p><p>2. Cocokkan tabel dengan sumber.</p><p>3. Simpan, lalu lihat Hasil.</p></div><button id="dismiss-welcome">Mengerti</button></section>`;}
async function uploadPage(){const s=current();$('#content').innerHTML=`${welcomeHTML()}<div class="hero-strip"><div><span class="eyebrow">MASUKKAN → CEK → SIMPAN</span><h1>Masukkan pricelist Anda.</h1><p>Gambar diproses setelah Anda menekan Proses. File tabel langsung dibaca di perangkat.</p></div>${canEdit()?'<div class="actions"><button id="sample">Coba contoh</button><button id="manual">＋ Isi manual</button></div>':''}</div>${canEdit()?`<div class="dropzone" id="drop" role="button" tabindex="0" aria-label="Pilih atau taruh file pricelist"><h3>Taruh file di sini atau pilih dari perangkat</h3><p>JPG, PNG, PDF, XLSX, CSV, TSV, TXT · antrean 10 file · 5 MB/file · total 25 MB</p><button id="pick" class="primary">Pilih file</button></div>`:'<p>Akun Viewer dapat melihat data dan laporan tim.</p>'}${state.sources.length?`<div class="source-list">${state.sources.map((x,i)=>`<button data-source="${i}" class="${i===state.selected?'selected':''}">${esc(x.supplier||x.filename)}${x.dirty?' •':''}<small>${esc(x.valid_from||'Tanggal belum dipilih')} · ${x.rows.length} baris</small></button>`).join('')}</div>`:''}${s?`<section class="panel"><div class="panel-body"><h3>1. Konfirmasi sumber</h3><p class="subtle">${esc(s.filename)}${s.sample?' · Contoh latihan; tidak disimpan ke database tim.':''}</p><div class="inline-grid"><label>PT / pemasok<input id="supplier" value="${esc(s.supplier)}" placeholder="Nama PT"></label><label>Mulai berlaku<input id="from" type="date" value="${esc(s.valid_from)}"></label><label>Akhir berlaku jika diketahui<input id="to" type="date" value="${esc(s.valid_to)}"></label></div><div class="actions">${s.file&&!/\.(xlsx|csv|tsv|txt|json)$/i.test(s.filename)?'<button id="process" class="primary">'+(s.rows.length?'Baca ulang':'Baca otomatis')+'</button><button id="cancel-ocr" '+(!state.busy?'hidden':'')+'>Batalkan proses</button>':''}<span id="progress" role="status" aria-live="polite">${esc(s.status)}</span></div><div class="ocr-progress" id="ocr-progress" ${!state.busy?'hidden':''}><progress id="ocr-meter" max="100" aria-label="Progres OCR keseluruhan"></progress><span id="ocr-percent">Menyiapkan…</span><small>Persiapan → Deteksi tabel → Baca kolom → Periksa baris</small></div><p id="summary"></p><div id="source-warnings">${warningsHTML(s)}</div><details class="reading-details"><summary>Lanjutan: format, kolom, dan bantuan AI</summary><label>Format angka di sumber<select id="source-locale"><option value="en-US" ${s.locale==='en-US'?'selected':''}>US: 35,000.50</option><option value="id-ID" ${s.locale==='id-ID'?'selected':''}>Indonesia: 35.000,50</option></select></label><div class="actions">${s.rawTable?'<button id="map-table">Pilih kolom tabel</button>':''}<button id="ai-image" ${!s.file||state.busy?'disabled':''}>Bantu baca dengan AI</button><button id="ai-review">Periksa teks dengan AI</button><button id="bulk-fields">Isi satuan / kondisi bersama</button></div><p>Mode lokal tidak mengirim gambar ke provider. Bantuan AI memakai koneksi Admin setelah persetujuan Anda. Tampilan dan ekspor harga memakai format US.</p></details></div></section><div class="upload-layout"><section class="panel source-panel"><div class="panel-head"><h3>Sumber</h3><small>Preview lokal; gambar tidak diarsipkan</small></div><div class="preview-local">${sourcePreview(s)}</div><div id="raw-text-slot">${s.rawText?`<details><summary>Teks mentah OCR</summary><pre>${esc(s.rawText)}</pre><button id="paste-table">Susun dari teks yang dikoreksi</button></details>`:''}</div></section><section class="panel result-panel"><div class="panel-head"><h3>2. Cek hasil</h3><button id="add-row">＋ Baris</button></div><div class="panel-body actions"><button data-filter="all" class="${state.filter==='all'?'selected':''}">Semua</button><button data-filter="issues" class="${state.filter==='issues'?'selected':''}">Perlu dicek (${s.rows.filter(r=>issues(r,state.items).length).length})</button><button data-filter="unmapped" class="${state.filter==='unmapped'?'selected':''}">Belum dikategorikan</button><label class="row-sort">Urutkan<select id="row-sort"><option value="source">Urutan sumber</option><option value="name">Nama A–Z</option><option value="category">Kategori item</option><option value="amount">Harga terendah</option></select></label><input id="row-search" aria-label="Cari barang" placeholder="Cari nama / kode barang" value="${esc(state.search??'')}"></div><div class="panel-body review-filter-note"><p id="review-visibility" aria-live="polite"></p><button id="show-all-rows" hidden>Tampilkan semua baris</button></div><div class="table-wrap"><table class="edit-table"><thead><tr><th>No.</th><th>Barang dari PT</th><th>Harga IDR</th><th>Satuan</th><th>Kondisi</th><th>Kategori item standar</th><th>Baris</th></tr></thead><tbody id="rows"></tbody></table></div><div class="panel-body"><div class="actions"><button id="previous">←</button><span id="page-label"></span><button id="next">→</button></div><div class="actions"><button id="save" class="primary" ${!canEdit()||state.busy||s.sample?'disabled':''}>Simpan</button><details class="save-options"><summary>Draft / unduh / copy</summary><div class="actions"><button id="save-draft" ${!canEdit()||state.busy||s.sample?'disabled':''}>Simpan sementara di web</button><button id="excel">Unduh Excel</button><button id="copy">Copy tabel</button></div></details></div><p id="draft-status" class="subtle">${s.dirty?'Belum disimpan di web':'Tersimpan di web'}</p><p class="subtle">Semua baris ikut simpan/ekspor, termasuk yang tidak terlihat pada halaman ini. Barang tanpa kategori tetap bisa disimpan di arsip. Pilih kategori agar masuk Harga Seragam.</p></div></section></div>`:'<div class="notice">Setelah file dipilih, hasilnya dapat dikoreksi di sini sebelum disimpan.</div>'}`;
if($('#dismiss-welcome'))$('#dismiss-welcome').onclick=()=>{state.welcomeHidden=true;try{localStorage.setItem('mis-welcome:'+state.user.id,'seen');}catch{}$('#dismiss-welcome').closest('section').remove();};if($('#sample'))$('#sample').onclick=()=>{const x=sourceState('Contoh latihan');x.sample=true;x.supplier='PT Contoh (simulasi)';x.valid_from=new Date().toISOString().slice(0,10);x.rows=[rawRow({product:'Produk contoh A',amount:12345,unit:'kg',condition:'frozen',basis:'Data fiktif untuk latihan'},x.filename),rawRow({product:'Produk contoh B',amount:23456,unit:'pack',pack:'500 g',basis:'Data fiktif untuk latihan'},x.filename)];x.status='Contoh fiktif · coba koreksi, kategori dan konversi';state.sources.push(x);state.selected=state.sources.length-1;state.page=0;state.filter='all';uploadPage();};if($('#pick')){$('#pick').onclick=e=>{e.stopPropagation();$('#file-input').click();};$('#drop').onclick=()=>$('#file-input').click();$('#drop').onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();$('#file-input').click();}};for(const k of ['dragenter','dragover'])$('#drop').addEventListener(k,e=>{e.preventDefault();$('#drop').classList.add('over');});$('#drop').ondragleave=()=>$('#drop').classList.remove('over');$('#drop').ondrop=e=>{e.preventDefault();addFiles(e.dataTransfer.files);};$('#manual').onclick=()=>{const x=sourceState('Input manual');x.rows=[rawRow({},'Input manual')];x.status='Isi tabel, lalu simpan';state.sources.push(x);state.selected=state.sources.length-1;state.page=0;uploadPage();};}
document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>{state.selected=+b.dataset.source;state.page=0;uploadPage();});if(!s)return;
for(const [selector,key]of [['#supplier','supplier'],['#from','valid_from'],['#to','valid_to']])$(selector).oninput=e=>{s[key]=e.target.value;changed(s);};$('#supplier').onchange=()=>{mapApproved(s);renderRows(s);};
if($('#process'))$('#process').onclick=e=>task(e.target,()=>processAutomatic(s));if($('#cancel-ocr'))$('#cancel-ocr').onclick=()=>state.controller?.abort();
$('#source-locale').onchange=e=>{s.locale=e.target.value;for(const r of s.rows)if(!r.user_amount&&r.raw_amount)r.amount=money(r.raw_amount,s.locale);changed(s);renderRows(s);};
$('#ai-image').onclick=e=>task(e.target,()=>processAI(s));$('#ai-review').onclick=e=>task(e.target,async()=>{if(s.rows.length>100)throw Error('Pilih maksimal 100 baris untuk review teks; proses gambar lokal tidak memakai kuota.');const r=await api('/review-table','POST',{rows:s.rows});detail('Usulan pemeriksaan AI',`<p>AI hanya menerima teks, bukan gambar sumber.</p><pre>${esc(r.text)}</pre>`);});
$('#add-row').onclick=()=>{s.rows.push(rawRow({source_row:s.rows.length+1},s.filename));changed(s);revealAllRows(s,s.rows.length-1);};$('#bulk-fields').onclick=()=>bulkFields(s);if($('#map-table'))$('#map-table').onclick=()=>tableSettings(s);$('#save-draft').onclick=e=>task(e.target,()=>saveSource(s,false));$('#save').onclick=()=>confirmSave(s);$('#excel').onclick=e=>task(e.target,()=>exportRows(exportSource(s),s.supplier||'Harga'));$('#copy').onclick=e=>task(e.target,async()=>{const cols=['supplier','product','standard_item','amount','unit','condition','size','sku','pack','minimum_order','valid_from','source'];await navigator.clipboard.writeText([cols.join('\t'),...exportSource(s).map(r=>cols.map(k=>tsvSafe(r[k])).join('\t'))].join('\n'));toast('Tabel disalin. Data belum tersimpan di web jika Anda belum menekan Simpan.');});
$('#show-all-rows').onclick=()=>revealAllRows(s);document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;state.page=0;renderRows(s);});let searchTimer;$('#row-search').oninput=e=>{state.search=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{state.page=0;renderRows(s);},120);};$('#row-sort').onchange=e=>{sortRows(s.rows,e.target.value);state.page=0;changed(s);renderRows(s);};$('#previous').onclick=()=>{state.page=Math.max(0,state.page-1);renderRows(s);};$('#next').onclick=()=>{state.page++;renderRows(s);};
if($('#reattach'))$('#reattach').onclick=()=>{state.reattach=s;$('#file-input').click();};if($('#paste-table'))$('#paste-table').onclick=()=>pasteTable(s);if($('#render-pdf'))$('#render-pdf').onclick=e=>task(e.target,()=>renderPDF(s,+$('#pdf-page').value));bindSourceZoom($('.source-panel'));renderRows(s);}
function categoryOptions(r){return (r.item_id&&!r.category_id?'<option value="__legacy__" disabled selected>Mapping lama — pilih kategori</option>':'')+'<option value="">Arsip saja / belum dipilih</option>'+STANDARD_ITEMS.map(c=>`<option value="${c.id}" ${r.category_id===c.id?'selected':''}>${esc(c.name)}</option>`).join('');}
function unitOptions(unit){return '<option value="">Pilih satuan</option>'+[...new Set([...UNITS,...(unit?[unit]:[])])].map(u=>`<option ${unit===u?'selected':''}>${esc(u)}</option>`).join('');}
function sourceFields(r,i){return `${[['sku','Kode PT'],['size','Ukuran'],['cut','Potongan'],['pack','Kemasan'],['minimum_order','Minimum order'],['region','Wilayah'],['channel','Channel'],['basis','Basis pajak/ongkir'],['notes','Catatan']].map(([k,label])=>`<label>${label}<input aria-label="${label} baris ${i+1}" data-row="${i}" data-key="${k}" value="${esc(r[k])}"></label>`).join('')}`;}
function rowHTML(r,i){const problems=issues(r,state.items),price=normalizedPrice(r);return `<tr data-index="${i}" class="${problems.length?'needs-review':''}"><td class="row-number" data-label="Baris">${i+1}</td><td data-label="Barang dari PT"><input aria-label="Nama barang baris ${i+1}" class="product-input" data-row="${i}" data-key="product" value="${esc(r.product)}"><small class="source-tier" ${!r.minimum_order?'hidden':''}>Minimum order / tier: ${esc(r.minimum_order)}</small><small class="source-weight" ${!r.pack?'hidden':''}>Berat/kemasan sumber: ${esc(r.pack)}</small><small class="row-issues">${esc(problems.join(' · '))}</small><details class="row-extra"><summary>Detail sumber (opsional)</summary><p class="subtle">Referensi dan teks asli untuk mencocokkan OCR; detail SKU, ukuran, kemasan, dan minimum order dapat dikoreksi di sini.</p><p>${esc(r.source)}${r.raw_product?' · Asli: '+esc(r.raw_product):''}</p><div class="inline-grid" data-extra-fields></div></details></td><td data-label="Harga IDR"><input aria-label="Harga baris ${i+1}, format US" inputmode="decimal" data-row="${i}" data-key="amount" value="${r.amount??''}" class="${r.amount===null?'bad':''}"></td><td data-label="Satuan"><select aria-label="Satuan baris ${i+1}" data-row="${i}" data-key="unit">${unitOptions(r.unit)}</select><button class="conversion-button" data-convert="${i}" ${!r.unit||r.unit==='kg'?'hidden':''}>${r.conversion?'Edit hitungan':'Konversi ke KG'}</button><small class="conversion-result">${r.conversion&&price?.unit==='kg'?'IDR '+rp(price.amount)+' / kg':r.conversion?'Konfirmasi hitungan':''}</small></td><td data-label="Kondisi"><select aria-label="Kondisi baris ${i+1}" data-row="${i}" data-key="condition">${['lainnya','fresh','frozen'].map(x=>`<option ${r.condition===x?'selected':''}>${x}</option>`).join('')}</select></td><td data-label="Item standar"><select aria-label="Kategori item baris ${i+1}" data-category="${i}">${categoryOptions(r)}</select><button class="shared-category" data-multi-category="${i}">＋ Pilih beberapa item</button>${r.mapping_group?'<small>Harga sumber bersama · tiap item disimpan terpisah</small>':''}<small>${r.item_id&&!r.category_id?'Mapping lama dipertahankan sampai kategori dipilih.':''}</small></td><td data-label="Aksi baris"><div class="row-actions"><button data-insert="${i}" aria-label="Tambah baris setelah ${i+1}">＋</button><button data-move="${i}" data-delta="-1" aria-label="Naikkan baris ${i+1}" ${i===0?'disabled':''}>↑</button><button data-move="${i}" data-delta="1" aria-label="Turunkan baris ${i+1}" ${i===current().rows.length-1?'disabled':''}>↓</button><button class="danger" data-delete="${i}" aria-label="Hapus baris ${i+1}">Hapus</button></div></td></tr>`;}
function revealAllRows(s,index=0){state.filter='all';state.search='';state.page=Math.floor(Math.max(0,index)/PAGE_SIZE);if($('#row-search'))$('#row-search').value='';renderRows(s);}
function multipleCategoryForm(s,index){const r=s.rows[index];const existing=new Set((r.mapping_group?s.rows.filter(x=>x.mapping_group===r.mapping_group):[r]).map(x=>x.category_id).filter(Boolean));detail('Pilih beberapa item standar',`<p><strong>${esc(r.product)}</strong> · IDR ${rp(r.amount)} / ${esc(r.unit||'satuan belum dipilih')}</p><p>Gunakan jika satu harga pada sumber memang berlaku untuk beberapa item, misalnya Paha bawah/atas. Setiap item menjadi baris tersendiri dengan harga dan referensi sumber yang sama. Jangan gunakan untuk ukuran yang hanya beririsan.</p><form id="multi-category-form"><div class="category-checks">${STANDARD_ITEMS.map(c=>`<label><input type="checkbox" name="category" value="${c.id}" ${existing.has(c.id)?'checked disabled':''}> ${esc(c.name)}${existing.has(c.id)?' (sudah dipilih)':''}</label>`).join('')}</div><label><input name="confirmed" type="checkbox" required> Harga dan spesifikasi pada sumber memang berlaku untuk seluruh item yang saya pilih.</label><button class="primary">Terapkan pilihan</button></form>`);$('#multi-category-form').onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{const f=e.target;const result=addCategoryCopies(s.rows,index,new FormData(f).getAll('category'),f.elements.confirmed.checked);changed(s);$('#detail').close();revealAllRows(s,index);toast('Pilihan diterapkan · '+result.created+' baris tambahan. Periksa tiap item sebelum Simpan.');});};}
function renderRows(s){if(!$('#rows'))return;const page=reviewPage(s.rows,state.items,{filter:state.filter,search:state.search,page:state.page});state.page=page.page;$('#rows').innerHTML=page.rows.map(({r,i})=>rowHTML(r,i)).join('')||'<tr><td colspan="7">Tidak ada baris pada filter ini. Pilih Semua untuk melihat tabel.</td></tr>';$('#review-visibility').textContent=page.count+' dari '+s.rows.length+' baris sesuai filter'+(s.rows.length>page.count?' · '+(s.rows.length-page.count)+' baris tersembunyi, bukan terhapus.':'.');$('#show-all-rows').hidden=page.count===s.rows.length;$('#page-label').textContent='Halaman '+(state.page+1)+'/'+page.pages+' · '+page.count+' baris';$('#previous').disabled=!state.page;$('#next').disabled=state.page>=page.pages-1;const checkButton=document.querySelector('[data-filter="issues"]');if(checkButton)checkButton.textContent='Perlu dicek ('+page.issues+')';document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter===state.filter));
const body=$('#rows');body.querySelectorAll('.row-extra').forEach(el=>el.ontoggle=()=>{const target=el.querySelector('[data-extra-fields]');if(el.open&&!target.hasChildNodes()){const i=+el.closest('tr').dataset.index;target.innerHTML=sourceFields(s.rows[i],i);}});body.oninput=e=>{const el=e.target;if(el.matches('input[data-row]'))updateCell(s,el);};body.onchange=e=>{const el=e.target;if(el.matches('select[data-row]'))updateCell(s,el);if(el.matches('[data-category]')){const r=s.rows[+el.dataset.category];r.category_id=el.value||null;r.category_origin='manual';r.item_id=null;r.item_snapshot=null;r.in_comparison=Boolean(r.category_id);changed(s);refreshRowStatus(el.closest('tr'),r);}};body.onfocusin=e=>{const tr=e.target.closest('tr[data-index]');if(tr)highlight(s.rows[+tr.dataset.index]);};body.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.multiCategory!==undefined)return multipleCategoryForm(s,+b.dataset.multiCategory);if(b.dataset.convert!==undefined)return conversionForm(s,+b.dataset.convert);if(b.dataset.delete!==undefined){const i=+b.dataset.delete,removed=s.rows.splice(i,1)[0];state.undoRow={source:s,row:removed,index:i};changed(s);revealAllRows(s,Math.max(0,i-1));showUndo();toast('Hanya baris '+(i+1)+' dihapus · '+s.rows.length+' baris lain tetap ada. Semua baris ditampilkan.');}if(b.dataset.insert!==undefined){const i=+b.dataset.insert+1;s.rows.splice(i,0,rawRow({source_row:s.rows.length+1},s.filename));changed(s);revealAllRows(s,i);}if(b.dataset.move!==undefined){moveRow(s.rows,+b.dataset.move,+b.dataset.delta);changed(s);revealAllRows(s,+b.dataset.move+(+b.dataset.delta));}};updateSummary(s);showUndo();}
function showUndo(){let el=$('#undo-row');if(!el){el=document.createElement('button');el.id='undo-row';$('#page-label')?.parentElement.append(el);}el.hidden=state.undoRow?.source!==current();el.textContent='Batalkan hapus baris';el.onclick=()=>{const x=state.undoRow;if(!x)return;x.source.rows.splice(x.index,0,x.row);state.undoRow=null;changed(x.source);revealAllRows(x.source,x.index);};}
function refreshRowStatus(tr,r){if(!tr)return;tr.querySelector('[data-category]').value=r.category_id||(r.item_id?'__legacy__':'');const tierLabel=tr.querySelector('.source-tier');tierLabel.hidden=!r.minimum_order;tierLabel.textContent='Minimum order / tier: '+(r.minimum_order??'');const weightLabel=tr.querySelector('.source-weight');weightLabel.hidden=!r.pack;weightLabel.textContent='Berat/kemasan sumber: '+(r.pack??'');const problems=issues(r,state.items);tr.classList.toggle('needs-review',Boolean(problems.length));tr.querySelector('.row-issues').textContent=problems.join(' · ');const b=tr.querySelector('[data-convert]');b.hidden=!r.unit||r.unit==='kg';b.textContent=r.conversion?'Edit hitungan':'Konversi ke KG';const price=normalizedPrice(r);tr.querySelector('.conversion-result').textContent=r.conversion&&price?.unit==='kg'?'IDR '+rp(price.amount)+' / kg':r.conversion?'Konfirmasi hitungan':'';}
function updateCell(s,el){const r=s.rows[+el.dataset.row],k=el.dataset.key;r[k]=k==='amount'?money(el.value):el.value;if(k==='amount'){r.user_amount=true;el.classList.toggle('bad',r.amount===null);}if(k==='unit')r.conversion=null;if(['product','unit','condition','pack','size','cut','sku'].includes(k)){r.item_id=null;r.item_snapshot=null;if(r.category_origin==='approved-rule'){r.category_id=null;r.in_comparison=false;r.category_origin=null;}}r.reviewed=false;changed(s);refreshRowStatus(el.closest('tr'),r);}
function conversionForm(s,i){const r=s.rows[i],fixed=r.unit==='g'?.001:r.unit==='ton'?1000:null;detail('Konversi harga ke KG',`<p><strong>${esc(r.product)}</strong> · Harga sumber IDR ${rp(r.amount)} / ${esc(r.unit)}</p><form id="conversion-form"><label>Berat bersih untuk 1 ${esc(r.unit)} (kg)<input name="weight" type="number" min="0.000001" max="10000" step="any" value="${r.conversion?.net_weight_kg??fixed??parseSourceWeight(r.pack)?.kg??''}" ${fixed?'readonly':''} required></label><p id="conversion-preview" class="calculation" role="status"></p><p>Rumus: harga sumber ÷ berat bersih satu satuan. Edit harga sumber di tabel atau ubah berat di sini. Jangan memakai titik tengah rentang ukuran ayam.</p><label><input name="confirmed" type="checkbox" ${r.conversion?.confirmed?'checked':''} required> Berat bersih sesuai sumber / sudah diverifikasi.</label><div class="actions"><button class="primary">Terapkan perhitungan</button><button type="button" id="remove-conversion">Gunakan satuan asli</button></div></form>`);const f=$('#conversion-form'),draw=()=>{$('#conversion-preview').textContent=Number(f.elements.weight.value)>0?'IDR '+rp(r.amount)+' ÷ '+f.elements.weight.value+' kg = IDR '+rp(convertPrice(r.amount,+f.elements.weight.value))+' / kg':'Isi berat bersih untuk melihat perhitungan.';};f.elements.weight.oninput=draw;draw();f.onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{r.conversion=checkedConversion(r.unit,{net_weight_kg:+f.elements.weight.value,confirmed:f.elements.confirmed.checked});r.item_id=null;changed(s);$('#detail').close();renderRows(s);});};$('#remove-conversion').onclick=()=>{r.conversion=null;changed(s);$('#detail').close();renderRows(s);};}
function bulkFields(s){detail('Isi atribut bersama',`<p>Berlaku untuk ${s.rows.length} baris dalam file ${esc(s.filename)}. Harga tidak diubah.</p><form id="bulk-form"><label>Satuan yang sudah terverifikasi<select name="unit"><option value="">Pertahankan</option>${UNITS.map(u=>`<option>${u}</option>`).join('')}</select></label><label>Kondisi<select name="condition"><option value="">Pertahankan</option><option>fresh</option><option>frozen</option><option>lainnya</option></select></label><button class="primary">Terapkan ke seluruh baris file ini</button></form>`);$('#bulk-form').onsubmit=e=>{e.preventDefault();if(!confirm('Terapkan satuan/kondisi pada seluruh '+s.rows.length+' baris file ini? Pemetaan lama yang terpengaruh akan dilepas.'))return;for(const r of s.rows){const old=signature(r);if(e.target.unit.value)r.unit=e.target.unit.value;if(e.target.condition.value)r.condition=e.target.condition.value;if(old!==signature(r)){r.item_id=null;r.in_comparison=Boolean(r.category_id);r.conversion=null;}}mapApproved(s);changed(s);$('#detail').close();renderRows(s);};}
function exportSource(s){return s.rows.map(r=>({...r,supplier:s.supplier,valid_from:s.valid_from,valid_to:s.valid_to,standard_item:category(r.category_id)?.name??state.items.find(x=>x.id===r.item_id)?.name??'',comparison_amount:r.conversion?convertPrice(r.amount,r.conversion.net_weight_kg):r.amount,comparison_unit:r.conversion?'kg':r.unit,status:s.dirty?'draft':s.status}));}
function proposeMetadata(s){const proposed=filenameMetadata(s.filename);Object.assign(s,proposed);if(Object.keys(proposed).length)s.warnings.push('PT/tanggal diusulkan dari nama file. Periksa terhadap pricelist sebelum final.');}
async function addFiles(files){if(state.busy){toast('Tunggu atau batalkan OCR sebelum menambah file.',true);return;}const incoming=[...files];if(state.reattach){const s=state.reattach;state.reattach=null;const f=incoming[0];if(!f)return;const hash=await fileHash(f);if(s.source_hash&&s.source_hash!==hash){toast('File berbeda dari sumber draft. Pilih file asli yang sesuai.',true);return;}s.file=f;s.url=URL.createObjectURL(f);s.mime=f.type||s.mime;s.source_hash=hash;uploadPage();return;}if(incoming.length+state.sources.filter(x=>x.file).length>10||incoming.reduce((n,f)=>n+f.size,0)+state.sources.reduce((n,s)=>n+(s.file?.size??0),0)>25*1024*1024){toast('Antrean maksimal 10 file dan total 25 MB. Simpan pekerjaan yang sudah selesai dahulu.',true);return;}for(const f of incoming){if(f.size>5*1024*1024){toast(f.name+': maksimum 5 MB.',true);continue;}if(!/\.(png|jpe?g|pdf|xlsx|csv|tsv|txt|json)$/i.test(f.name)){toast('Format tidak didukung: '+f.name,true);continue;}const s=sourceState(f.name,f);s.source_hash=await fileHash(f);if(!s.mime)s.mime=/\.pdf$/i.test(f.name)?'application/pdf':/\.png$/i.test(f.name)?'image/png':/\.jpe?g$/i.test(f.name)?'image/jpeg':'application/octet-stream';proposeMetadata(s);state.sources.push(s);state.selected=state.sources.length-1;if(/\.(xlsx|csv|tsv|txt|json)$/i.test(f.name))await task(null,()=>readTableFile(s));}state.page=0;show('upload');}
async function fileHash(f){const bytes=await crypto.subtle.digest('SHA-256',await f.arrayBuffer());return [...new Uint8Array(bytes)].map(x=>x.toString(16).padStart(2,'0')).join('');}
$('#file-input').onchange=e=>{task(null,()=>addFiles(e.target.files));e.target.value='';};
async function processLocal(s){if(state.busy)throw Error('Satu OCR berjalan pada satu waktu.');if(s.rows.length&&!confirm('Proses ulang akan mengganti tabel pada file ini. Lanjutkan?'))return;state.busy=true;state.controller=new AbortController();lockUpload(true);if($('#ocr-meter'))$('#ocr-meter').value=0;if($('#ocr-percent'))$('#ocr-percent').textContent='0%';if($('#ocr-progress'))$('#ocr-progress').hidden=false;if($('#cancel-ocr'))$('#cancel-ocr').hidden=false;let lastProgress=0;const progress=(m,percent)=>{s.status=m;const box=$('#ocr-progress');if(box)box.hidden=false;if(Number.isFinite(percent)&&$('#ocr-meter')){$('#ocr-meter').value=Math.max(Number($('#ocr-meter').value)||0,percent);$('#ocr-percent').textContent=Math.round($('#ocr-meter').value)+'%';}if(performance.now()-lastProgress>180&&current()===s&&$('#progress')){$('#progress').textContent=m;lastProgress=performance.now();}};try{const {localOCR}=await import('./ocr.js');if(s.locale==='en-US'&&/wahana|sulaiman|belsmart|chikin|september/i.test(s.filename))s.locale='id-ID';const out=await measureStage('ocr',()=>localOCR(s,{locale:s.locale,signal:state.controller.signal,onProgress:progress}));s.rows=out.rows;state.filter=s.rows.some(r=>issues(r,state.items).length)?'issues':'all';state.page=0;s.rawText=out.rawText;s.warnings.push(...out.warnings);mapApproved(s);s.status='Draft OCR · pasangan item, harga, satuan dan tier belum diverifikasi';changed(s);}catch(e){s.status='OCR gagal · '+e.message;s.warnings.push('Proses terbaru gagal. '+(s.rows.length?'Tabel sebelumnya dipertahankan; bukan hasil proses terbaru.':'Belum ada hasil harga yang dapat digunakan.'));throw e;}finally{state.busy=false;state.controller=null;lockUpload(false);refreshUploadResult(s);}}
async function processAI(s){if(state.busy)throw Error('Tunggu proses aktif selesai.');state.busy=true;lockUpload(true);try{return await processAIRequest(s);}finally{state.busy=false;lockUpload(false);refreshUploadResult(s);}}
async function processAIRequest(s){requireUser();if(!s.file)throw Error('Pilih ulang file sumber.');if(s.mime==='application/pdf')throw Error('Untuk bantuan AI, pilih gambar/potongan halaman PDF. OCR lokal PDF tersedia.');if(s.file.size>2*1024*1024)throw Error('Bantuan AI maksimal 2 MB/potongan. Gunakan OCR lokal atau pilih potongan yang terbaca.');if(!confirm('Kirim gambar ini ke provider AI yang diatur Admin? Hasil akan menjadi usulan pengganti tabel; gambar tidak diarsipkan aplikasi.'))return;const bytes=new Uint8Array(await s.file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));if($('#ocr-progress'))$('#ocr-progress').hidden=false;if($('#ocr-meter'))$('#ocr-meter').removeAttribute('value');if($('#ocr-percent'))$('#ocr-percent').textContent='Menunggu Gemini / AI…';if($('#progress'))$('#progress').textContent='Mengirim gambar dan menunggu hasil AI (maks. 2 menit)…';const r=await api('/extract','POST',{data:btoa(binary),mime:s.mime,consent:true});let parsed;try{parsed=parseAIExtraction(r.output.text);}catch{detail('Hasil AI belum lengkap',`<pre>${esc(r.output.text)}</pre>`);throw Error('Tabel AI tidak valid atau belum lengkap. Tabel lama dipertahankan. Gunakan potongan lebih kecil atau isi manual.');}if(!Array.isArray(parsed.rows))throw Error('AI tidak memberi tabel.');if(s.rows.length&&!confirm('Gunakan '+parsed.rows.length+' baris usulan AI menggantikan tabel ini?'))return;s.rows=parsed.rows.map(x=>rawRow({...x,flags:[...(Array.isArray(x.flags)?x.flags:[]),'Hasil AI perlu diperiksa terhadap sumber']},s.filename));s.warnings.push(...(parsed.warnings??[]).map(String));if(parsed.complete===false)s.warnings.push('AI menyatakan hasil belum lengkap. Jangan final sebelum rekonsiliasi sumber.');s.status='Usulan AI · '+r.output.model+' · perlu diperiksa';mapApproved(s);state.filter=s.rows.some(r=>issues(r,state.items).length)?'issues':'all';state.page=0;changed(s);}
function sheetTable(ws){if(!ws)return [];const rows=[];if(ws.rowCount>5000||ws.columnCount>100)throw Error('Pilih sheet maksimal 5.000 baris dan 100 kolom untuk preview; simpan dibatasi 500 baris/batch.');ws.eachRow(row=>rows.push(row.values.slice(1).map(v=>{if(v&&typeof v==='object'&&!(v instanceof Date))throw Error('Formula/rich text perlu diekspor sebagai values terlebih dahulu.');return v??'';})));return rows;}
async function readTableFile(s){if(/\.xlsx$/i.test(s.filename)){await asset('/vendor/exceljs.min.js');const wb=new ExcelJS.Workbook();await wb.xlsx.load(await s.file.arrayBuffer());s.workbook=wb;s.sheetName=wb.worksheets[0]?.name;s.rawTable=sheetTable(wb.worksheets[0]);}else if(/\.json$/i.test(s.filename)){const data=JSON.parse(await s.file.text());if(!Array.isArray(data.entries))throw Error('JSON harus cadangan entries dari aplikasi tim.');s.rawTable=[['company','tanggal','product','price','unit','condition'],...data.entries.map(x=>[x.company??'',x.date??x.week??'',x.product??'',x.price??'',x.unit??'',x.condition??''])];s.warnings.push('Cadangan lama: periksa tanggal, satuan dan PT terhadap sumber.');}else{const text=await s.file.text();const delimiters=/\.tsv$/i.test(s.filename)?['\t']:['\t',',',';'];let chosen=null;for(const d of delimiters){const rows=parseDelimited(text,d);if(rows.some(r=>r.length>1)&&(!chosen||rows[0].length>chosen[0].length)){chosen=rows;s.delimiter=d;}}s.rawTable=chosen??parseDelimited(text);}
 if(s.rawTable.length>5000||s.rawTable.some(r=>r.length>100))throw Error('Preview maksimal 5.000 baris dan 100 kolom. File tidak dipotong; pisahkan file sumber.');const detected=detectTable(s.rawTable);if(detected){applyTable(s,detected);s.status='Tabel dibaca otomatis · periksa hasil';}else{s.status='Kolom belum jelas; pilih pembacaan file';s.warnings.push('Pilih kolom barang/harga melalui Ubah pembacaan file. Tidak ada baris dipotong.');}changed(s);}
function applyTable(s,config){const oldGroups=state.sources.filter(x=>x.tableParent===s.id);if(oldGroups.some(x=>x.batch_id))throw Error('Sebagian kelompok sudah tersimpan. Impor ulang sebagai file baru agar arsip tidak tertimpa.');state.sources=state.sources.filter(x=>x.tableParent!==s.id);const {header,fields:f}=config;const groups=new Map();for(const [index,row]of s.rawTable.slice(header+1).entries()){if(!row.some(v=>String(v??'').trim()))continue;const value=k=>f[k]>=0?row[f[k]]:'';const product=String(value('product')??'');if(!product.trim())continue;const supplier=String(value('supplier')||s.supplier),date=excelDate(value('date'))||s.valid_from,key=JSON.stringify([supplier,date]);if(!groups.has(key))groups.set(key,[]);const c=norm(value('condition'));const r=rawRow({product,amount:value('amount'),raw_amount:value('amount'),unit:String(value('unit')||''),condition:['fresh','frozen'].includes(c)?c:'lainnya',sku:String(value('sku')??''),size:String(value('size')??''),pack:String(value('pack')??''),channel:String(value('channel')||''),basis:String(value('basis')||'belum diketahui'),source:s.filename+' · '+(s.sheetName||'tabel')+' · baris '+(header+index+2)+' kolom '+(f.amount+1)},s.filename,s.locale);if(value('condition')&&c==='fresh/frozen')r.flags.push('Kondisi sumber Fresh/Frozen; konfirmasi sebelum membandingkan');groups.get(key).push(r);}
 let count=0;for(const [key,rows]of groups){const [supplier,date]=JSON.parse(key),target=count++===0?s:sourceState(s.filename);target.rows=rows;target.supplier=supplier;target.valid_from=date;target.locale=s.locale;target.status='Tabel dibaca · periksa hasil';target.source_hash=s.source_hash;if(target!==s)target.tableParent=s.id;mapApproved(target);if(target!==s)state.sources.push(target);}s.tableConfig=config;if(s.rows.length>500)s.warnings.push('Hasil melebihi 500 baris. Semua tersedia untuk ekspor; pisahkan file/kelompok sebelum simpan.');}
function tableSettings(s){if(!s.rawTable?.length)return;const h=s.tableConfig?.header??0,headers=s.rawTable[h].map(String),config=s.tableConfig?.fields??{},fields={product:'Nama barang',amount:'Harga biasa',supplier:'PT',date:'Tanggal',unit:'Satuan',condition:'Kondisi',sku:'Kode barang',size:'Ukuran',pack:'Kemasan',channel:'Channel',basis:'Basis'};detail('Ubah pembacaan tabel',`${s.workbook?`<label>Sheet<select id="sheet">${s.workbook.worksheets.map(w=>`<option ${w.name===s.sheetName?'selected':''}>${esc(w.name)}</option>`).join('')}</select></label>`:''}<label>Baris header (mulai 1)<input id="header-row" type="number" min="1" max="${Math.min(20,s.rawTable.length)}" value="${h+1}"></label><form id="table-map" class="form-grid">${Object.entries(fields).map(([k,label])=>`<label>${label}<select name="${k}"><option value="-1">Tidak ada / isi manual</option>${headers.map((x,i)=>`<option value="${i}" ${config[k]===i?'selected':''}>${esc(x||'Kolom '+(i+1))}</option>`).join('')}</select></label>`).join('')}<button class="primary">Baca ulang tabel</button></form><p>Tidak ada formula dijalankan. Harga biasa dipilih terpisah dari HORECA.</p>`);if($('#sheet'))$('#sheet').onchange=e=>{s.sheetName=e.target.value;s.rawTable=sheetTable(s.workbook.getWorksheet(s.sheetName));s.tableConfig=detectTable(s.rawTable);tableSettings(s);};$('#header-row').onchange=e=>{s.tableConfig={header:Math.min(s.rawTable.length-1,Math.max(0,+e.target.value-1)),fields:{}};tableSettings(s);};$('#table-map').onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{const f=Object.fromEntries([...new FormData(e.target)].map(([k,v])=>[k,+v]));if(f.product<0||f.amount<0||f.product===f.amount)throw Error('Pilih kolom barang dan harga yang berbeda.');if(s.rows.length&&!confirm('Baca ulang mengganti koreksi tabel file ini. Lanjutkan?'))return;applyTable(s,{header:+$('#header-row').value-1,fields:f});changed(s);$('#detail').close();uploadPage();});};}
function pasteTable(s){detail('Susun tabel dari teks',`<p>Tempel tabel dengan header barang, harga, satuan; gunakan tab antar kolom. Hasil menjadi usulan yang bisa diperiksa.</p><textarea id="pasted-table" rows="12">${esc(s.rawText??'')}</textarea><button id="parse-paste" class="primary">Baca tabel</button>`);$('#parse-paste').onclick=()=>{s.rawTable=parseDelimited($('#pasted-table').value,'\t');s.tableConfig=detectTable(s.rawTable);$('#detail').close();if(s.tableConfig){applyTable(s,s.tableConfig);changed(s);uploadPage();}else tableSettings(s);};}
async function renderPDF(s,page){const pdfjs=await import('/vendor/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc='/vendor/pdf.worker.mjs';const pdf=await pdfjs.getDocument({data:new Uint8Array(await s.file.arrayBuffer()),isEvalSupported:false,useSystemFonts:true}).promise;try{if(page<1||page>pdf.numPages)throw Error('PDF mempunyai '+pdf.numPages+' halaman.');const p=await pdf.getPage(page),canvas=$('#pdf-canvas');if(!canvas)return;const vp=p.getViewport({scale:1.25});canvas.width=vp.width;canvas.height=vp.height;await p.render({canvasContext:canvas.getContext('2d'),viewport:vp}).promise;$('#pdf-page').max=pdf.numPages;}finally{await pdf.destroy();}}
function confirmSave(s){const problems=finalProblems(s),rules=reusableCategoryRules(s.rows);detail('Simpan harga',`<p><strong>${esc(s.supplier||'PT belum diisi')}</strong> · ${esc(s.valid_from||'Tanggal belum diisi')} · ${s.rows.length} baris</p><p>${s.rows.filter(r=>r.category_id).length} baris berkategori masuk daftar harga seragam. Baris lainnya tetap disimpan di arsip PT.</p>${problems.length?'<div class="inline-error" role="status"><strong>Perbaiki sebelum konfirmasi:</strong><ul>'+problems.slice(0,12).map(p=>'<li>'+esc(p)+'</li>').join('')+'</ul>'+(problems.length>12?'<p>'+problems.length+' masalah total.</p>':'')+'</div>':''}<label><input type="checkbox" id="checked-source"> Saya sudah memeriksa seluruh hasil dan kelengkapan terhadap sumber.</label>${isAdmin()?'<label><input type="checkbox" id="remember-categories"> Ingat pilihan kategori tunggal untuk upload berikutnya dari PT ini (aturan Admin).</label>':''}${rules.ambiguous.length?`<p class="notice">${rules.ambiguous.length} nama/SKU dipakai untuk beberapa item. Semua baris tetap disimpan; pilihan tersebut tidak dijadikan aturan global karena aturan saat ini hanya mendukung satu item per identitas.</p>`:''}<div class="actions"><button id="final-save" class="primary">Simpan & konfirmasi harga</button><button id="keep-draft">Simpan sebagai draft</button></div>`);$('#final-save').onclick=e=>task(e.target,async()=>{if(!$('#checked-source').checked)throw Error('Centang pemeriksaan sumber terlebih dahulu.');const problems=finalProblems(s);if(problems.length)throw Error(problems.slice(0,5).join(' '));if($('#remember-categories')?.checked){const rows=rules.rows.map(r=>Object.fromEntries(['product','raw_product','sku','condition','unit','pack','size','cut','category_id'].map(k=>[k,r[k]])));if(rows.length){await api('/category-rules','POST',{supplier:s.supplier,rows});await loadMaster(true);}}for(const r of s.rows)r.reviewed=true;await saveSource(s,true);$('#detail').close();});$('#keep-draft').onclick=e=>task(e.target,async()=>{await saveSource(s,false);$('#detail').close();});}
async function saveSource(s,approve=false){if(s.sample)throw Error('Contoh latihan tidak disimpan ke database tim. Unggah pricelist asli untuk menyimpan.');if(s.saving)throw Error('Penyimpanan masih berjalan. Tunggu sampai selesai.');s.saving=true;try{await saveSourceOnce(s,approve);}finally{s.saving=false;}}
async function saveSourceOnce(s,approve=false){requireUser();if(!canEdit())throw Error('Akun ini hanya dapat membaca.');if(!s.rows.length)throw Error('Belum ada hasil tabel.');if(s.rows.length>500)throw Error('Maksimal 500 observasi per penyimpanan. Semua baris tetap ada; pisahkan file atau unduh dahulu.');const payload={supplier:s.supplier,valid_from:s.valid_from,valid_to:s.valid_to,filename:s.filename,document_id:null,rows:s.rows.map(r=>({...r,source:r.source||s.filename||'Input manual',source_hash:s.source_hash??''})),request_id:s.id,revision:s.revision};const version=s.changeVersion??0;const response=await api('/batches'+(s.batch_id?'/'+s.batch_id:''),s.batch_id?'PATCH':'POST',payload);if(!s.batch_id)s.batch_id=response.id;s.revision=response.revision??(s.revision+1);s.status='Draft tersimpan di web';s.dirty=(s.changeVersion??0)!==version;let confirmed=false;try{if(approve){if(s.dirty)throw Error('Ada koreksi saat penyimpanan. Simpan ulang sebelum konfirmasi.');await api('/batches/'+s.batch_id+'/approve','POST',{revision:s.revision});s.revision++;confirmed=true;s.status='Harga dikonfirmasi';if((s.changeVersion??0)!==version){s.batch_id=null;s.id=newId();s.revision=1;s.dirty=true;s.status='Koreksi lanjutan · draft baru';}else s.readonly=true;}}finally{if(!s.dirty&&(!approve||confirmed)){if(s.url)URL.revokeObjectURL(s.url);s.url='';s.file=null;s.rawTable=null;s.workbook=null;}await persist();if(state.view==='upload')await uploadPage();}if(approve&&!s.dirty){state.sources=state.sources.filter(x=>x!==s);state.selected=Math.max(0,state.sources.length-1);show('archive');}toast(approve?'Harga tersimpan dan dikonfirmasi.':'Draft tersimpan di web. Anda dapat melanjutkan dari Data Harga.');}
async function archivePage(){
 $('#content').innerHTML=`<div class="hero-strip"><div><h1>Daftar harga seragam</h1><p>Kategori adalah nama item standar. Pilih kategori saat memeriksa upload; hanya harga terkonfirmasi yang tampil di sini.</p></div><button id="new-standard-upload" class="primary">＋ Tambah harga</button></div><div class="actions"><button class="selected">Harga seragam</button><button id="source-archive">Arsip PT & tanggal</button></div>${filtersHTML()}<div class="toolbar"><label>Ringkasan<select id="matrix-mode"><option value="weekly">Rata-rata mingguan</option><option value="daily">Per tanggal sumber</option></select></label><label>Satuan hasil<select id="matrix-unit"><option value="kg">KG (termasuk konversi terverifikasi)</option><option value="">Semua satuan, dipisah per baris</option>${UNITS.filter(u=>u!=='kg').map(u=>`<option>${u}</option>`).join('')}</select></label><label>Kondisi<select id="matrix-condition"><option value="">Semua, dipisah per baris</option><option>fresh</option><option>frozen</option><option>lainnya</option></select></label><button id="matrix-excel">Unduh Excel seragam</button><button id="matrix-copy">Copy tabel seragam</button></div><div id="matrix-results"></div>`;
 $('#new-standard-upload').onclick=()=>show('upload');$('#source-archive').onclick=()=>task(null,sourceArchivePage);let matrix,page=0;
 const columns=['Company','Tahun','Periode Harga (week)','Tanggal Harga',...STANDARD_ITEMS.map(c=>c.name)];
 const values=r=>[r.company,r.year,'W'+String(r.week).padStart(2,'0'),r.dates.join(', '),...STANDARD_ITEMS.map(c=>r.values[c.id]?.amount??'')];
 const draw=()=>{if(!state.compiled){$('#matrix-results').innerHTML='<p>Pilih rentang tanggal, lalu Tampilkan kompilasi.</p>';return;}matrix=standardMatrix(state.compiled.groups,{mode:$('#matrix-mode').value,unit:$('#matrix-unit').value,condition:$('#matrix-condition').value,from:state.compiled.from,to:state.compiled.to});const pages=Math.max(1,Math.ceil(matrix.rows.length/50));page=Math.min(page,pages-1);$('#matrix-results').innerHTML=`<div class="notice">${matrix.rows.length} baris Company/periode/konteks · ${matrix.excluded} observasi belum berkategori. ${state.compiled.excluded??0} observasi arsip tidak disertakan. ${$('#matrix-mode').value==='weekly'?'Rata-rata seluruh update valid pada minggu Senin–Minggu; Tahun mengikuti tahun week ISO.':'Setiap tanggal sumber dipertahankan.'} Kosong = tidak ada data; ⚠ = konflik yang perlu dikoreksi. Kondisi, satuan, kemasan, MOQ, channel, wilayah dan basis berbeda tetap dipisah.</div><div class="table-wrap standard-matrix"><table><thead><tr>${columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${matrix.rows.slice(page*50,page*50+50).map((r,j)=>`<tr><td>${esc(r.company)}<small>${esc(r.context.filter(Boolean).join(' · '))}${r.missing?' · Tidak ada update minggu ini':''}</small></td><td>${r.year}</td><td>W${String(r.week).padStart(2,'0')}<small>Mulai ${esc(r.week_start)}</small></td><td>${esc(r.dates.join(', ')||'Tidak ada update')}</td>${STANDARD_ITEMS.map(c=>{const v=r.values[c.id];return `<td>${v?`<button class="link" data-matrix-row="${page*50+j}" data-matrix-category="${c.id}">${v.conflict?'⚠ Konflik':rp(v.amount)}</button><small>${v.count} update</small>`:'—'}</td>`;}).join('')}</tr>`).join('')||`<tr><td colspan="26">Belum ada harga seragam untuk filter ini. Buka arsip, pilih kategori pada draft/koreksi, lalu konfirmasi.</td></tr>`}</tbody></table></div><div class="actions matrix-pagination"><button id="matrix-prev" ${page===0?'disabled':''}>←</button><span>Halaman ${page+1}/${pages}</span><button id="matrix-next" ${page>=pages-1?'disabled':''}>→</button></div>`;$('#matrix-prev').onclick=()=>{page--;draw();};$('#matrix-next').onclick=()=>{page++;draw();};document.querySelectorAll('[data-matrix-row]').forEach(b=>b.onclick=()=>{const r=matrix.rows[+b.dataset.matrixRow],c=category(b.dataset.matrixCategory),cell=r.values[c.id];detail(c.name+' · '+r.company,`<p>${esc(r.context.filter(Boolean).join(' · '))}</p>${cell.sources.map(q=>`<section class="notice"><strong>IDR ${rp(q.amount)} / ${esc(q.unit)}</strong><p>${esc(q.product)} · ${esc(q.valid_from)}<br>${esc(q.source)}${q.original_amount!==undefined?'<br>Asli: IDR '+rp(q.original_amount)+' / '+esc(q.original_unit)+' ÷ '+q.conversion.net_weight_kg+' kg':''}</p></section>`).join('')}`);});};
 $('#range-form').onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{state.compiled=await api('/compile?'+new URLSearchParams(new FormData(e.target)));page=0;draw();});};for(const id of ['#matrix-mode','#matrix-unit','#matrix-condition'])$(id).onchange=()=>task(null,async()=>{page=0;draw();});
 $('#matrix-copy').onclick=e=>task(e.target,async()=>{if(!matrix)throw Error('Tampilkan data dahulu.');await navigator.clipboard.writeText([columns.join('\t'),...matrix.rows.map(r=>values(r).map(tsvSafe).join('\t'))].join('\n'));toast('Seluruh halaman tabel seragam disalin.');});
 $('#matrix-excel').onclick=e=>task(e.target,async()=>{if(!matrix)throw Error('Tampilkan data dahulu.');await asset('/vendor/exceljs.min.js');const wb=new ExcelJS.Workbook(),ws=wb.addWorksheet('Harga Seragam');const extra=['Kondisi','Satuan','Kemasan','Channel','Wilayah','Basis','Minimum order'];ws.addRow([...columns,...extra]);for(const r of matrix.rows)ws.addRow([...values(r),...r.context]);ws.getRow(1).font={bold:true};ws.views=[{state:'frozen',xSplit:4,ySplit:1}];ws.columns.forEach((c,i)=>{c.width=i<4?22:26;if(i>=4&&i<26)c.numFmt='#,##0.00';});download(await wb.xlsx.writeBuffer(),'Harga-Seragam-'+state.compiled.from+'-'+state.compiled.to+'.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');});
 if(!state.compiled){const d=defaultDates();try{state.compiled=await api('/compile?'+new URLSearchParams(d));}catch(e){toast(e.message,true);}}draw();
}
async function sourceArchivePage(){const {batches}=await api('/batches');const folders=new Map();for(const b of batches){const key=b.supplier||'Belum lengkap';if(!folders.has(key))folders.set(key,[]);folders.get(key).push(b);}$('#content').innerHTML=`<div class="hero-strip"><div><h1>Data harga tim.</h1><p>Seluruh sumber tetap tersimpan per PT dan periode. Gambar asli berada pada backup lokal Anda.</p></div><button id="new-upload" class="primary">＋ Tambah harga</button></div><div class="actions"><button id="standard-view">Harga seragam</button><button class="selected">Arsip PT & tanggal</button><button id="compare-view">Bandingkan harga</button>${isAdmin()?'<button id="catalog-view">Daftar barang pembanding</button>':''}</div>${[...folders].map(([name,list])=>`<details class="folder" open><summary>${esc(name)} · ${list.length} pricelist</summary><table><thead><tr><th>Periode</th><th>Dokumen</th><th>Status</th><th></th></tr></thead><tbody>${list.map(b=>`<tr><td>${esc(b.valid_from||'Belum lengkap')}<small>${esc(b.valid_to||'Akhir belum diketahui')}</small></td><td>${esc(b.filename)}<small>Revisi ${b.revision} · ${esc(b.updated_at)}</small></td><td>${esc(({draft:'Draft',approved:'Dikonfirmasi',archived:'Ditarik'})[b.status])}</td><td><button data-batch="${esc(b.id)}">Buka</button></td></tr>`).join('')}</tbody></table></details>`).join('')||'<div class="notice">Belum ada data. Mulai dari Tambah Harga.</div>'}`;$('#new-upload').onclick=()=>show('upload');$('#standard-view').onclick=()=>archivePage();$('#compare-view').onclick=()=>show('compile');if($('#catalog-view'))$('#catalog-view').onclick=()=>catalogPage();document.querySelectorAll('[data-batch]').forEach(b=>b.onclick=()=>task(b,()=>openBatch(b.dataset.batch)));}
async function catalogPage(){await loadMaster();$('#content').innerHTML=`<h1>Daftar barang pembanding</h1><p>Pilih barang yang memang ingin dianalisis. Barang lain tetap disimpan pada pricelist PT; tidak wajib dipetakan semua.</p><div class="actions"><button id="back-data">← Data Harga</button><button id="new-catalog" class="primary">＋ Barang pembanding</button></div>${state.items.map(i=>`<section class="panel"><div class="panel-body"><h3>${esc(i.name)}</h3><p>${esc([i.condition,i.unit,i.pack,JSON.parse(i.spec_json||'{}').size].filter(Boolean).join(' · '))}</p><small>${state.aliases.filter(a=>a.item_id===i.id).length} aturan nama/kode PT</small></div></section>`).join('')||'<p>Belum ada barang pembanding. Tambahkan item prioritas pertama.</p>'}`;$('#back-data').onclick=()=>show('archive');$('#new-catalog').onclick=()=>itemForm(catalogPage);}
async function openBatch(id){const b=await api('/batches/'+id);detail((b.supplier||'PT belum lengkap')+' · '+(b.valid_from||'tanggal kosong'),`<p>${esc(b.filename)} · ${esc(b.status)} · revisi ${b.revision}</p><p>${b.rows.length} baris · ${b.rows.filter(r=>r.item_id&&r.in_comparison!==false).length} pembanding</p><div class="table-wrap"><table><thead><tr><th>Barang PT</th><th>Harga</th><th>Barang pembanding</th></tr></thead><tbody>${b.rows.map(r=>`<tr><td>${esc(r.product)}</td><td>${rp(r.amount)} / ${esc(r.unit)}</td><td>${esc(r.item_snapshot?.name||state.items.find(i=>i.id===r.item_id)?.name||'Belum masuk pembanding')}</td></tr>`).join('')}</tbody></table></div><div class="actions">${canEdit()?`<button id="edit-batch" class="primary">${b.status==='draft'?'Lanjutkan draft':'Salin ke draft koreksi'}</button>${b.status!=='archived'?'<button id="withdraw-batch" class="danger">Tarik dari kompilasi</button>':''}`:''}<button id="batch-excel">Unduh Excel sumber</button></div><p>Harga final tidak ditimpa. Untuk koreksi, salin ke draft baru dan tarik versi lama sebelum final agar tidak terjadi konflik.</p>`);if($('#edit-batch'))$('#edit-batch').onclick=()=>{const x=sourceState(b.filename);Object.assign(x,{supplier:b.supplier,valid_from:b.valid_from,valid_to:b.valid_to,rows:b.rows.map(r=>rawRow(r,b.filename)),batch_id:b.status==='draft'?b.id:null,revision:b.status==='draft'?b.revision:1,status:'Data dari web · pilih ulang gambar bila perlu',dirty:b.status!=='draft',source_hash:b.rows[0]?.source_hash??''});state.sources.push(x);state.selected=state.sources.length-1;$('#detail').close();show('upload');};if($('#withdraw-batch'))$('#withdraw-batch').onclick=e=>task(e.target,async()=>{if(!confirm('Tarik versi ini dari kompilasi? Histori dan laporan tersimpan tetap ada.'))return;await api('/batches/'+b.id+'/archive','POST',{revision:b.revision});$('#detail').close();show('archive');});$('#batch-excel').onclick=e=>task(e.target,()=>exportRows(b.rows.map(r=>({...r,supplier:b.supplier,valid_from:b.valid_from,valid_to:b.valid_to,status:b.status})),b.supplier||'Harga'));}
function defaultDates(){const d=new Date(),to=d.toISOString().slice(0,10);d.setUTCDate(d.getUTCDate()-27);return {from:d.toISOString().slice(0,10),to};}
function filtersHTML(report=false){const d=state.compiled??defaultDates();return `<form id="range-form" class="toolbar"><label>Dari tanggal<input name="from" type="date" value="${esc(d.from)}" required></label><label>Sampai tanggal<input name="to" type="date" value="${esc(d.to)}" required></label><label>PT (kosong = semua)<input name="supplier" value="${esc(d.supplier??'')}" placeholder="Filter PT"></label><button class="primary">${report?'Analisis range':'Tampilkan kompilasi'}</button></form>`;}
async function compilePage(){await loadMaster();$('#content').innerHTML=`<div class="hero-strip"><div><h1>Satu standar, banyak sumber.</h1><p>Barang pembanding × PT. Angka adalah rata-rata update dalam rentang pilihan; klik untuk melihat sumber. Hanya data terkonfirmasi.</p></div><button id="master" ${!isAdmin()?'hidden':''}>＋ Item standar</button></div>${filtersHTML()}<div id="compile-results"></div>`;$('#range-form').onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{const q=new URLSearchParams(new FormData(e.target));state.compiled=await api('/compile?'+q);renderCompile();});};$('#master').onclick=()=>itemForm(()=>compilePage());if(state.compiled)renderCompile();}
function renderCompile(){const d=state.compiled,pt=[...new Set(d.groups.flatMap(g=>g.suppliers.map(s=>s.supplier)))];$('#compile-results').innerHTML=`<div class="notice">${esc(d.warning)} · ${d.metrics.observation_count} observasi · ${d.metrics.conflicts} konflik · ${d.excluded??0} observasi belum disertakan karena bukan pembanding. PT kosong atau harga tidak sebanding tidak diisi nol.</div><div class="actions"><button id="compile-excel">Download Excel detail</button><button id="to-report">Analisis & Report →</button></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Item standar / konteks</th>${pt.map(p=>`<th>${esc(p)}</th>`).join('')}</tr></thead><tbody>${d.groups.map((g,i)=>`<tr><td>${esc(g.name)}<small>${esc([g.condition,g.unit,g.pack,g.size,g.cut,g.channel,g.region,g.basis,g.minimum_order].filter(Boolean).join(' · '))}</small></td>${pt.map(p=>{const s=g.suppliers.find(s=>s.supplier===p);return `<td>${s?`<button class="link" data-cell="${i}" data-pt="${esc(p)}">${s.conflict?'⚠ Konflik':rp(s.average)}</button><small>${esc(s.latest?.valid_from||'Periksa sumber')}</small>`:'<span class="subtle">Tidak ada data</span>'}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div></section>`;$('#compile-excel').onclick=e=>task(e.target,()=>exportRows(d.groups.flatMap(g=>g.quotes.map(r=>({...r,standard_item:g.name}))), 'Kompilasi_'+d.from+'_'+d.to));$('#to-report').onclick=()=>show('analysis');document.querySelectorAll('[data-cell]').forEach(b=>b.onclick=()=>{const g=d.groups[Number(b.dataset.cell)],s=g.suppliers.find(s=>s.supplier===b.dataset.pt);detail('Sumber '+g.name,`<p>${esc(b.dataset.pt)} · ${s.conflict?'Konflik: jangan dipakai sebagai harga tunggal.':'Observasi terbaru dalam range.'}</p>${s.quotes.map(q=>`<div class="notice">${esc(q.product)} · Rp${rp(q.amount)} / ${esc(q.unit)}<br>${esc(q.valid_from)} s.d. ${esc(q.valid_to||'belum diketahui')}<br>${esc(q.source)}<br>${esc(q.filename||'Harga pilot lama')} · revisi ${q.batch_revision??q.revision??1}</div>`).join('')}`);});}
async function analysisPage(){
 $('#content').innerHTML=`<h1>Analisis harga mingguan</h1><p>Minggu Senin–Minggu. Rata-rata update per PT/barang/basis yang sama; minggu kosong tidak diisi nol.</p>${filtersHTML(true)}<div id="analysis-results"></div>`;
 const draw=()=>{if(!state.compiled)return;const d=state.compiled;$('#analysis-results').innerHTML=`<div class="notice">${d.metrics.company_count} PT · ${d.metrics.observation_count} observasi · ${d.metrics.conflicts} konflik · ${d.excluded??0} observasi di luar pembanding. ${esc(d.warning)}</div><button id="make-report" class="primary">Buat laporan dari periode ini →</button>${d.metrics.series.map(s=>`<section class="panel"><div class="panel-body"><h3>${esc(s.name)} · ${esc(s.supplier)}</h3><p>${esc([s.condition,s.unit,s.minimum_order,s.channel,s.region].filter(Boolean).join(' · '))}${s.conflict?' · ⚠ Konflik sumber; tidak menjadi headline':''}</p><div class="table-wrap"><table><thead><tr><th>Awal minggu</th><th>Rata-rata IDR</th><th>Jumlah update</th><th>Min–maks</th></tr></thead><tbody>${weeksInRange(d.from,d.to,s.points).map(p=>`<tr><td>${esc(p.week)}</td><td>${rp(p.amount)}</td><td>${p.count??0}${p.missing?' · Tidak ada update':''}</td><td>${p.missing?'—':rp(p.min??p.amount)+'–'+rp(p.max??p.amount)}</td></tr>`).join('')}</tbody></table></div></div></section>`).join('')||'<p>Belum ada data pembanding terkonfirmasi pada periode ini.</p>'}`;$('#make-report').onclick=()=>{state.report=null;show('reports');};};
 $('#range-form').onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{state.compiled=await api('/compile?'+new URLSearchParams(new FormData(e.target)));state.report=null;draw();});};draw();
}
async function reportPage(){
 $('#content').innerHTML=`<h1>Laporan untuk management</h1><p>Preview, edit narasi lalu unduh PPTX/PDF. Angka berasal dari satu snapshot analisis.</p><button id="change-period">Ubah periode analisis</button><div id="report-area"></div>`;$('#change-period').onclick=()=>show('analysis');if(!state.compiled){$('#report-area').innerHTML='<p>Pilih periode pada Analisis dan tampilkan data terlebih dahulu.</p>';return;}state.report??=buildReport(state.compiled);renderReport();
}
function renderReport(){const report=state.report;$('#report-area').innerHTML=`<div class="notice">${report.metrics.company_count} PT · ${report.metrics.item_count} kelompok item setara · ${report.metrics.observation_count} observasi · periode ${esc(report.from)}–${esc(report.to)}. ${report.metrics.company_count<2?'Satu PT: bukan gambaran pasar.':''}</div><div class="actions"><button id="report-ai" ${!canEdit()?'disabled':''}>Usulkan insight AI</button><button id="pptx">Download PPTX</button><button id="pdf">Download PDF</button><button id="save-report" ${!canEdit()?'disabled':''}>Simpan report</button></div><p class="subtle">Judul dan poin narasi dapat diedit sebelum ekspor. Data grafik dan angka tetap mengikuti snapshot. Snapshot menyimpan data, filter, dan narasi yang sudah Anda tinjau.</p>${report.slides.map((s,i)=>`<section class="report-slide"><h2 contenteditable="true" data-slide-title="${i}">${esc(s.title)}</h2><ul>${s.bullets.map((p,j)=>`<li contenteditable="true" data-slide-point="${i}:${j}">${esc(p)}</li>`).join('')}</ul>${s.rows?`<div class="table-wrap"><table><thead><tr>${s.headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${s.rows.map(row=>`<tr>${row.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:''}${s.chart?chartSVG(s.chart):''}<small>${esc(report.from)}–${esc(report.to)} · snapshot ${esc(report.generated_at)} · Internal</small></section>`).join('')}`;document.querySelectorAll('[data-slide-title]').forEach(el=>el.oninput=()=>report.slides[Number(el.dataset.slideTitle)].title=el.textContent.slice(0,160));document.querySelectorAll('[data-slide-point]').forEach(el=>el.oninput=()=>{const [i,j]=el.dataset.slidePoint.split(':').map(Number);report.slides[i].bullets[j]=el.textContent.slice(0,600);});$('#report-ai').onclick=e=>task(e.target,async()=>{const output=await api('/report-insights','POST',{from:report.from,to:report.to,supplier:state.compiled.supplier??'',fingerprint:state.compiled.fingerprint});let proposed;try{proposed=JSON.parse(output.text.replace(/^```(?:json)?\s*/,'').replace(/\s*```$/,''));}catch{throw Error('Output AI belum terstruktur; coba lagi. Angka dan narasi tidak berubah.');}if(!['opportunities','actions'].every(k=>Array.isArray(proposed[k])&&proposed[k].length<=4&&proposed[k].every(v=>typeof v==='string'&&v.length<=600)))throw Error('Format insight AI tidak valid.');detail('Review usulan AI',`<p>Model ${esc(output.model)}. Periksa klaim terhadap sumber sebelum dipakai.</p><h3>Peluang</h3><ul>${proposed.opportunities.map(v=>`<li>${esc(v)}</li>`).join('')}</ul><h3>Aksi</h3><ul>${proposed.actions.map(v=>`<li>${esc(v)}</li>`).join('')}</ul><button class="primary" id="apply-insight">Saya sudah review, gunakan narasi ini</button>`);$('#apply-insight').onclick=()=>{report.slides[6].bullets=proposed.opportunities;report.slides[8].bullets=proposed.actions;$('#detail').close();renderReport();};});$('#pptx').onclick=e=>task(e.target,async()=>{await asset('/vendor/pptxgen.bundle.js');await exportPPTX(report);});$('#pdf').onclick=e=>task(e.target,async()=>{await asset('/vendor/jspdf.umd.min.js');await exportPDF(report);});$('#save-report').onclick=e=>task(e.target,async()=>{await api('/reports','POST',{fingerprint:state.compiled.fingerprint,name:'MIS Harga '+report.from+' — '+report.to,from:report.from,to:report.to,supplier:state.compiled.supplier??$('#range-form').supplier.value,narrative:report.slides.map(s=>({title:s.title,bullets:s.bullets}))});toast('Snapshot report tersimpan.');});}
function detail(title,html){$('#detail').querySelector('[data-dialog-error]')?.remove();$('#detail-title').textContent=title;$('#detail-body').innerHTML=html;if(!$('#detail').open)$('#detail').showModal();}
function itemForm(after){if(!isAdmin()){toast('Minta Admin menambahkan item standar.',true);return;}detail('Barang pembanding baru',`<form id="item-form" class="form-grid"><label class="wide">Nama standar + ukuran/grade<input name="name" required maxlength="200" placeholder="Contoh: Karkas 1,3–1,4 kg"></label><label>Kondisi<select name="condition"><option>fresh</option><option>frozen</option><option>lainnya</option></select></label><label>Satuan harga<input name="unit" value="kg" required></label><label>Kemasan<input name="pack"></label><label>Ukuran / grade<input name="size" placeholder="Kosong jika tidak dibedakan"></label><label>Potongan / spesifikasi<input name="cut"></label><label>Deskripsi spesifikasi<input name="description" placeholder="Kulit/tulang, grade, batas ukuran"></label><button class="primary">Tambah item standar</button></form><p class="subtle">Ukuran/kondisi berbeda harus menjadi item berbeda. Alias PT baru hanya diingat setelah disetujui Admin.</p>`);$('#item-form').onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{await api('/items','POST',Object.fromEntries(new FormData(e.target)));await loadMaster(true);$('#detail').close();await after?.();});};}
async function settingsPage(){if(!isAdmin())throw Error('Settings hanya untuk Admin.');const [settings,userList,preferences]=await Promise.all([api('/settings'),api('/users'),api('/preferences')]);const providers=settings.providers,users=userList.users;$('#content').innerHTML=`<div class="hero-strip"><div><h1>Koneksi dan akses tim.</h1><p>Hanya Admin dapat membaca/mengubah pengaturan API, model, dan user.</p></div></div><div class="notice">Budget gratis. OCR lokal tidak memerlukan key. Bantuan AI opsional; Gemini memakai daftar gratis terverifikasi bertanggal, OpenRouter dapat memakai openrouter/free. Pilihan model pada halaman ini dipakai bersama oleh proses tim.</div><section class="panel"><div class="panel-body"><label>Engine review teks & insight report<select id="review-engine"><option value="gemini" ${preferences.review_engine==='gemini'?'selected':''}>Gemini</option><option value="openrouter" ${preferences.review_engine==='openrouter'?'selected':''}>OpenRouter</option></select></label><label><input id="gemini-free" type="checkbox" ${preferences.gemini_free_confirmed?'checked':''}> Saya sudah memastikan proyek Gemini memakai kuota gratis tanpa billing aktif.</label><p class="subtle">Pilihan ini dipakai untuk bantuan gambar, pemeriksaan teks dan laporan. Tidak ada fallback otomatis ke provider lain.</p></div></section><div class="provider-grid">${['gemini','openrouter'].map(provider=>{const s=providers.find(x=>x.provider===provider);return `<section class="panel"><div class="panel-head"><h3>${provider==='gemini'?'Gemini':'OpenRouter'}</h3><span class="tag">${esc(s?.state??'Belum diatur')}</span></div><div class="panel-body"><form data-provider="${provider}"><label>API key<input type="password" name="key" autocomplete="new-password" placeholder="${s?'Kosongkan untuk mempertahankan key':'Masukkan key'}"></label><label>Cari / pilih model<select name="model" data-model-select="${provider}"><option value="${esc(s?.model??(provider==='gemini'?'auto-free':'openrouter/free'))}">${esc(s?.model??(provider==='gemini'?'Otomatis · kandidat gratis terverifikasi':'openrouter/free'))}</option></select></label><label>Filter daftar model<input data-model-filter="${provider}" placeholder="Ketik nama model setelah fetch"></label><label><input type="checkbox" name="consent" ${s?.consent?'checked':''}> Data yang diproses boleh dikirim ke provider ini.</label><p class="subtle">Provider gratis dapat memakai data untuk peningkatan model sesuai kebijakannya. Kirim hanya dokumen yang Anda izinkan; izin ini tidak menjamin kerahasiaan dari provider.</p><div class="actions"><button class="primary">Simpan</button><button type="button" data-fetch="${provider}">Fetch model</button><button type="button" data-test="${provider}">Tes koneksi</button><button type="button" data-delete="${provider}" class="danger">Hapus key</button></div><p class="subtle">${s?.tested_at?'Tes terakhir: '+esc(s.tested_at):'Belum dites'}. Fetch katalog bukan bukti inference berhasil. Model gambar memerlukan kemampuan visual. Fetch katalog bukan bukti akses inference atau sisa kuota.</p></form></div></section>`;}).join('')}</div><section class="panel"><div class="panel-head"><h3>Pengguna</h3></div><div class="panel-body"><form id="new-user" class="inline-grid"><label>Username<input name="username" required pattern="[A-Za-z0-9_.-]{3,50}"></label><label>Password sementara<input name="password" type="password" minlength="8" required autocomplete="new-password"></label><label>Role<select name="role"><option value="editor">Editor</option><option value="viewer">Viewer</option><option value="admin">Admin</option></select></label><button class="primary">Tambah user</button></form><div class="table-wrap"><table class="user-table"><thead><tr><th>Username</th><th>Role</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${users.map(x=>`<tr><td>${esc(x.username)}</td><td><select data-user-role="${esc(x.id)}">${['admin','editor','viewer'].map(r=>`<option ${x.role===r?'selected':''}>${r}</option>`).join('')}</select></td><td>${x.active?'Aktif':'Nonaktif'}</td><td><button data-user-save="${esc(x.id)}">Simpan role</button><button data-reset="${esc(x.id)}">Reset password</button><button data-active="${esc(x.id)}" data-value="${x.active?'0':'1'}">${x.active?'Nonaktifkan':'Aktifkan'}</button></td></tr>`).join('')}</tbody></table></div><p class="subtle">User baru/reset diminta mengganti password sementara. Password tidak dapat dilihat kembali. Admin aktif terakhir tidak dapat dinonaktifkan.</p></div></section><section class="panel"><div class="panel-head"><h3>Daftar barang pembanding</h3><button id="new-item">＋ Tambah</button></div><div class="panel-body">${state.items.map(i=>`<p>${esc(i.name)} · ${esc(i.condition)} · ${esc(i.unit)} · ${esc(i.pack||'tanpa detail kemasan')}</p>`).join('')||'<p>Belum ada item standar.</p>'}</div></section><button id="audit">Lihat audit terbaru</button>`;
const savePreferences=e=>task(e.target,async()=>{await api('/preferences','PATCH',{review_engine:$('#review-engine').value,gemini_free_confirmed:$('#gemini-free').checked});toast('Preferensi AI tim diperbarui.');});$('#review-engine').onchange=savePreferences;$('#gemini-free').onchange=savePreferences;document.querySelectorAll('[data-provider]').forEach(form=>form.onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{const s=providers.find(x=>x.provider===form.dataset.provider);await api('/settings/'+form.dataset.provider,'PUT',{key:form.key.value,model:form.model.value,consent:form.consent.checked,revision:s?.revision});form.key.value='';toast('Pengaturan tersimpan.');settingsPage();});});const catalog={};document.querySelectorAll('[data-fetch]').forEach(b=>b.onclick=()=>task(b,async()=>{const provider=b.dataset.fetch;const data=await api('/settings/'+provider+'/models','POST',{key:document.querySelector('[data-provider="'+provider+'"]')?.key.value});catalog[provider]=provider==='gemini'?[{id:'auto-free',label:'Otomatis · kandidat gratis terverifikasi'},...data.models]:data.models;renderModels(provider,'');toast(data.models.length+' model ditarik. Pilih dan Simpan, lalu Tes koneksi.');}));function renderModels(provider,q){const select=document.querySelector('[data-model-select="'+provider+'"]'),selected=select.value;select.innerHTML=(catalog[provider]??[]).filter(x=>norm(x.id+' '+x.label).includes(norm(q))).map(x=>`<option value="${esc(x.id)}" ${x.id===selected?'selected':''}>${esc(x.label)} · ${esc(x.id)}</option>`).join('');}document.querySelectorAll('[data-model-filter]').forEach(el=>el.oninput=()=>renderModels(el.dataset.modelFilter,el.value));document.querySelectorAll('[data-test]').forEach(b=>b.onclick=()=>task(b,async()=>{try{await api('/settings/'+b.dataset.test+'/test','POST',{});toast('Inference berhasil.');}finally{settingsPage();}}));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>task(b,async()=>{if(!confirm('Hapus key? Proses tim tidak dapat menggunakan provider ini sampai diatur lagi.'))return;await api('/settings/'+b.dataset.delete,'DELETE');settingsPage();}));$('#new-user').onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{await api('/users','POST',Object.fromEntries(new FormData(e.target)));e.target.reset();toast('User ditambahkan. Sampaikan password sementara secara privat.');settingsPage();});};document.querySelectorAll('[data-user-save]').forEach(b=>b.onclick=()=>task(b,async()=>{await api('/users/'+b.dataset.userSave,'PATCH',{role:document.querySelector('[data-user-role="'+b.dataset.userSave+'"]').value});toast('Role diperbarui; sesi user lama dibatalkan.');settingsPage();}));document.querySelectorAll('[data-reset]').forEach(b=>b.onclick=()=>{detail('Reset password',`<form id="reset-form"><label>Password sementara baru<input type="password" name="password" minlength="8" required autocomplete="new-password"></label><div class="dialog-actions"><button class="primary">Reset dan batalkan sesi</button></div></form>`);$('#reset-form').onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{await api('/users/'+b.dataset.reset,'PATCH',{password:e.target.password.value});e.target.reset();$('#detail').close();toast('Password direset.');settingsPage();});};});document.querySelectorAll('[data-active]').forEach(b=>b.onclick=()=>task(b,async()=>{if(!confirm('Ubah status akun ini dan batalkan sesi aktifnya?'))return;await api('/users/'+b.dataset.active,'PATCH',{active:b.dataset.value==='1'});settingsPage();}));$('#new-item').onclick=()=>itemForm(()=>settingsPage());$('#audit').onclick=()=>task(null,async()=>{const data=await api('/audit');detail('Audit terakhir',`<div class="history-list">${data.rows.map(x=>`<details><summary>${esc(x.at)} · ${esc(x.action)} · ${esc(x.session)}</summary><pre>${esc(x.detail)}</pre></details>`).join('')}</div>`);});}
async function exportRows(rows,name){await asset('/vendor/exceljs.min.js');const wb=new ExcelJS.Workbook();const groups=new Map();for(const row of rows){const key=(row.supplier||name)+(/wahana/i.test(row.supplier??'')?' '+row.condition:'');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(row);}if(!groups.size)groups.set(name,[]);let n=1;const used=new Set();for(const [key,data]of groups){let label=String(key).replace(/[\\/?*\[\]:]/g,' ').slice(0,25)||'Harga';while(used.has(label.toLowerCase()))label=label.slice(0,24)+' '+n++;used.add(label.toLowerCase());const ws=wb.addWorksheet(label,{views:[{state:'frozen',ySplit:1}]});const headers=['supplier','sku','product','standard_item','amount','unit','condition','size','cut','pack','minimum_order','channel','region','basis','valid_from','valid_to','source','comparison_amount','comparison_unit','status','notes','mapping_group'];ws.columns=headers.map(h=>({header:h,key:h,width:['product','source','standard_item'].includes(h)?35:19}));for(const row of data)ws.addRow(Object.fromEntries(headers.map(h=>[h,row[h]??''])));ws.getRow(1).font={bold:true};ws.autoFilter={from:{row:1,column:1},to:{row:1,column:headers.length}};ws.getColumn('amount').numFmt='"IDR" #,##0.00';}download(await wb.xlsx.writeBuffer(),name.replace(/[^\p{L}\p{N}_-]+/gu,'_')+'.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');}
const assets=new Map();function asset(url){if(!assets.has(url))assets.set(url,new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=url;s.onload=resolve;s.onerror=()=>{assets.delete(url);reject(Error('Library gagal dimuat. Periksa koneksi dan ulangi.'));};document.head.append(s);}));return assets.get(url);}
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function passwordForm(){detail('Ganti password',`<p>Ganti password sementara untuk membuka data tim.</p><form id="change-password"><label>Password sekarang<input name="current" type="password" required autocomplete="current-password"></label><label>Password baru<input name="password" type="password" minlength="8" required autocomplete="new-password"></label><div class="dialog-actions"><button class="primary">Simpan password</button></div></form>`);$('#change-password').onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{await api('/me/password','POST',{current:e.target.current.value,password:e.target.password.value});e.target.reset();state.user=null;state.sources=[];identity();$('#detail').close();login();});};}
function account(){if(!state.user){login();return;}detail('Akun '+state.user.username,`<p>Role: ${esc(state.user.role)}. Semua data tersimpan pada workspace tim internal yang sama.</p><div class="actions">${isAdmin()?'<button id="admin-settings">Pengaturan Admin</button>':''}<button id="my-password">Ganti password</button><button id="signout">Keluar</button></div>`);if($('#admin-settings'))$('#admin-settings').onclick=()=>{$('#detail').close();show('settings');};$('#my-password').onclick=passwordForm;$('#signout').onclick=e=>task(e.target,async()=>{if(state.sources.some(s=>!s.sample&&s.dirty&&s.rows.length)&&!confirm('Draft lokal akan dihapus saat keluar. Simpan sementara di web dahulu bila diperlukan. Tetap keluar?'))return;clearTimeout(draftTimer);clearTimeout(draftMax);draftMax=null;await draftStore(state.user.id,null);await api('/logout','POST',{});state.user=null;state.items=[];state.aliases=[];state.compiled=null;state.report=null;state.sources=[];identity();$('#content').replaceChildren();$('#detail').close();login();});}
$('#login-form').onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{try{const r=await api('/login','POST',{username:e.target.username.value,password:e.target.password.value});state.user=r.user;e.target.reset();$('#login').close();identity();if(state.user.must_change){passwordForm();return;}await loadMaster();show(state.view);}catch(error){$('#login-error').textContent=error.message;}});};
$('#top-account').onclick=account;$('#account').onclick=account;document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>show(b.dataset.view));window.addEventListener('beforeunload',e=>{if(state.sources.some(s=>!s.sample&&s.dirty&&s.rows.length)){persist();e.preventDefault();e.returnValue='';}});document.addEventListener('paste',e=>{if(['INPUT','TEXTAREA'].includes(document.activeElement?.tagName))return;const files=[...(e.clipboardData?.files??[])];if(files.length)addFiles(files);});
async function start(){try{state.user=(await api('/session')).user;identity();if(!state.user){login();return;}if(state.user.must_change){passwordForm();return;}$('#content').innerHTML='<p role="status">Menyiapkan workspace…</p>';await measureStage('startup',async()=>{const [status]=await Promise.all([api('/status'),loadMaster()]);state.status=status;});try{const local=await draftStore(state.user.id);if(local?.sources?.length&&confirm('Ada '+local.sources.length+' draft pada perangkat ini. Lanjutkan pekerjaan?')){state.sources=local.sources;for(const x of state.sources)x.url='';}}catch(e){toast(e.message,true);}await uploadPage();}catch(e){$('#workspace').hidden=true;toast(e.message,true);}}
window.addEventListener('pagehide',()=>{$('#workspace').hidden=true;});window.addEventListener('pageshow',event=>{if(event.persisted)start();});
await start();
